static class NativePreviewSoundChecks {
 static int total;static void Yes(bool value,string label){if(!value)throw new Exception(label);total++;Console.WriteLine("PASS\t"+label);}static SoundMix Mix(JObject pose)=>SoundMix.Parse(pose["sound"]);
 static int Main(){try{var c=new LibraryPreviewController();c.Manager.Client.Cache["selected/left"]=new SoundMix(.13f,.27f,true,true);var first=c.TestPose();var mix=Mix(first);Yes(mix.Music==.13f&&mix.Effects==.27f&&mix.MusicMuted&&mix.EffectsMuted,"first pose carries target volume and both mute controls");Yes(c.Manager.Client.LastDisplay=="left","uses selected target rather than work global sound");for(int i=0;i<8;i++){mix=Mix(c.TestPose());Yes(mix.MusicGain==0&&mix.EffectsGain==0,"subsequent pose "+i+" preserves user mute");}c.Manager.Client.Cache["selected/left"]=new SoundMix(.31f,.12f,false,true);mix=Mix(c.TestPose());Yes(mix.Music==.31f&&!mix.MusicMuted&&mix.EffectsMuted,"saved sidebar cache change reaches next pose");c.Manager.Client.Cache["selected/right"]=new SoundMix(.42f,.53f,true,false);c.TargetDisplayId="right";mix=Mix(c.TestPose());Yes(mix.Music==.42f&&mix.Effects==.53f&&mix.MusicMuted&&!mix.EffectsMuted,"target switch reads its own independent mix");c.TestLoad(c.Selected).GetAwaiter().GetResult();Yes(Mix(SpatialWallpaper.Desktop.NativePreviewTarget.Config["pose"] as JObject).Music==.42f,"actual load configuration uses same target sound pose");c.Selected=new SpatialWallpaper.Library.Artwork{Id="different",Source=SpatialWallpaper.Library.ArtworkSource.SdkNative};c.Manager.Client.Cache["different/right"]=new SoundMix(.99f,.99f);mix=Mix(c.TestPose());Yes(mix.Music==.42f&&c.Manager.Client.LastWork=="selected","loaded preview retains exact work while Library selection changes");first["sound"]["music"]=.99;Yes(Mix(c.TestPose()).Music==.42f,"pose JSON mutation cannot alter cached user mix");Yes(c.Manager.Client.Reads>=14,"pose reads synchronous in-memory cache only; no RPC API is supplied");c.TestRelease().GetAwaiter().GetResult();Yes(Mix(c.TestPose()).Music==.99f,"release clears previous preview work binding");Console.WriteLine("TOTAL\t"+total);return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
